+      try {
+        mkdirSync(this.hooksDir, { recursive: true });
+      } catch (error) {
+        log('Failed to create hooks directory:', error);
+        return [];
+      }
+    }
+
+    // Install commit-msg hook (parse #kb tags)
+    results.push(await this.installCommitMsgHook());
+
+    // Install post-commit hook (capture diffs)
